// QHPlanningServiceServer is the server API for QHPlanningService service.
// All implementations must embed UnimplementedQHPlanningServiceServer
// for forward compatibility
type QHPlanningServiceServer interface {
	// QHPlanningProject APIs
	CreatePlanningProject(context.Context, *PlanningProject) (*PlanningProject, error)
	GetPlanningProject(context.Context, *IdRequest) (*PlanningProject, error)
	CountPlanningProject(context.Context, *IdRequest) (*PlanningProjectCountResponse, error)
	UpdatePlanningProject(context.Context, *PlanningProject) (*PlanningProject, error)
	DeletePlanningProject(context.Context, *IdRequest) (*SubmitResponse, error)
	ListPlanningProjects(context.Context, *ListPlanningProjectsRequest) (*ListPlanningProjectsResponse, error)
	ListPlanningProjectLayers(context.Context, *ListPlanningProjectLayersRequest) (*ListLayersResponse, error)
	// Assign provinces to planning project
	AdminAssignProvinces(context.Context, *AdminAssignProvincesRequest) (*SubmitResponse, error)
	// Unassign provinces (delete relations)
	AdminUnassignProvinces(context.Context, *AdminUnassignProvincesRequest) (*SubmitResponse, error)
	// Assign wards to planning project
	AdminAssignWards(context.Context, *AdminAssignWardsRequest) (*SubmitResponse, error)
	// Unassign wards (delete relations)
	AdminUnassignWards(context.Context, *AdminUnassignWardsRequest) (*SubmitResponse, error)
	// UnassignPlanningProjectLayer gỡ layer khỏi đồ án: chỉ xóa layer_plan_doc_relation, không xóa layer.
	UnassignPlanningProjectLayer(context.Context, *UnassignPlanningProjectLayerRequest) (*SubmitResponse, error)
	// CreatePlanningProjectFromFolder tạo đồ án + toàn bộ tài liệu từ 1 folder admin chọn.
	// Mỗi file trong folder trở thành 1 PlanningDocument (trạng thái Pending, chờ job AI phân loại).
	CreatePlanningProjectFromFolder(context.Context, *CreatePlanningProjectFromFolderRequest) (*CreatePlanningProjectFromFolderResponse, error)
	// ApprovePlanningProject phê duyệt đồ án (chỉ khi đã Classified), đồng thời phê duyệt các tài liệu đã Classified.
	ApprovePlanningProject(context.Context, *IdRequest) (*PlanningProject, error)
	// RetryFailedPlanningDocuments đưa tất cả tài liệu Failed của đồ án về Pending để job classify chạy lại.
	RetryFailedPlanningDocuments(context.Context, *IdRequest) (*PlanningProject, error)
	GetPlanningProjectSeoSource(context.Context, *IdRequest) (*PlanningProjectSeoSourceResponse, error)
	UpdatePlanningProjectSeoID(context.Context, *UpdatePlanningProjectSeoIDRequest) (*SubmitResponse, error)
	AdminGenPlanningProjectSeo(context.Context, *AdminGenPlanningProjectSeoRequest) (*AdminGenPlanningProjectSeoResponse, error)
	// Pro AI Jobs — tiến trình AI (type Đồ án gắn planning_project_id).
	ListProAIJobs(context.Context, *ListProAIJobsRequest) (*ListProAIJobsResponse, error)
	GetProAIJob(context.Context, *IdRequest) (*ProAIJob, error)
	// QHPlanningDocument APIs
	CreatePlanningDocument(context.Context, *PlanningDocument) (*PlanningDocument, error)
	GetPlanningDocument(context.Context, *IdRequest) (*PlanningDocument, error)
	// UpdatePlanningDocument cập nhật toàn bộ thông tin tài liệu (loại, số liệu, ngày, cơ quan, ngành, lĩnh vực, người ký, ...).
	UpdatePlanningDocument(context.Context, *PlanningDocument) (*PlanningDocument, error)
	DeletePlanningDocument(context.Context, *IdRequest) (*SubmitResponse, error)
	ListPlanningDocuments(context.Context, *ListPlanningDocumentsRequest) (*ListPlanningDocumentsResponse, error)
	// ApprovePlanningDocument phê duyệt 1 tài liệu đã được AI phân loại (chỉ khi đang Classified).
	ApprovePlanningDocument(context.Context, *IdRequest) (*PlanningDocument, error)
	// RetryPlanningDocument đưa 1 tài liệu Failed về Pending để job classify chạy lại.
	RetryPlanningDocument(context.Context, *IdRequest) (*PlanningDocument, error)
	GetPlanningDocumentSeoSource(context.Context, *IdRequest) (*PlanningDocumentSeoSourceResponse, error)
	UpdatePlanningDocumentSeoID(context.Context, *UpdatePlanningDocumentSeoIDRequest) (*SubmitResponse, error)
	AdminGenPlanningDocumentSeo(context.Context, *AdminGenPlanningDocumentSeoRequest) (*AdminGenPlanningDocumentSeoResponse, error)
	// AssignPlanningDocumentsToLayer gán tài liệu vào layer (cartesian layerIds × docIds trên layer_plan_doc_relation).
	AssignPlanningDocumentsToLayer(context.Context, *AssignPlanningDocumentsToLayerRequest) (*SubmitResponse, error)
	// UnassignPlanningDocumentsFromLayer gỡ tài liệu khỏi layer: xóa cứng bản ghi layer_plan_doc_relation.
	UnassignPlanningDocumentsFromLayer(context.Context, *AssignPlanningDocumentsToLayerRequest) (*SubmitResponse, error)
	// Planning document legal histories.
	CreatePlanningDocumentHistory(context.Context, *PlanningDocumentHistory) (*PlanningDocumentHistory, error)
	DeletePlanningDocumentHistory(context.Context, *DeletePlanningDocumentHistoryRequest) (*SubmitResponse, error)
	ListPlanningDocumentHistories(context.Context, *ListPlanningDocumentHistoriesRequest) (*ListPlanningDocumentHistoriesResponse, error)
	// QHPlanningEvent APIs — lịch sử pháp lý / timeline đồ án.
	CreatePlanningEvent(context.Context, *PlanningEvent) (*PlanningEvent, error)
	GetPlanningEvent(context.Context, *IdRequest) (*PlanningEvent, error)
	UpdatePlanningEvent(context.Context, *PlanningEvent) (*PlanningEvent, error)
	DeletePlanningEvent(context.Context, *IdRequest) (*SubmitResponse, error)
	ListPlanningEvents(context.Context, *ListPlanningEventsRequest) (*ListPlanningEventsResponse, error)
	// QHPlanningRelation APIs — quan hệ đồ án (parent/child/peer).
	CreatePlanningRelation(context.Context, *PlanningRelation) (*PlanningRelation, error)
	GetPlanningRelation(context.Context, *IdRequest) (*PlanningRelation, error)
	UpdatePlanningRelation(context.Context, *PlanningRelation) (*PlanningRelation, error)
	DeletePlanningRelation(context.Context, *IdRequest) (*SubmitResponse, error)
	ListPlanningRelations(context.Context, *ListPlanningEventsRequest) (*ListPlanningRelationsResponse, error)
	// Client APIs
	// gRPC compatibility method. Client HTTP ownership belongs to PlanningClientService.
	ClientGetPlanningProject(context.Context, *IdRequest) (*PlanningProject, error)
	// gRPC compatibility method. Client HTTP ownership belongs to PlanningClientService.
	ClientGetPlanningDocument(context.Context, *IdRequest) (*PlanningDocument, error)
	ClientListPlanningEvents(context.Context, *ListPlanningEventsRequest) (*ListPlanningEventsResponse, error)
	ClientListPlanningRelations(context.Context, *ListPlanningEventsRequest) (*ListPlanningRelationsResponse, error)
	ClientCountPlanningProject(context.Context, *PlanningProjectIdRequest) (*PlanningProjectCountResponse, error)
	// List planning projects filtered by administrative unit (admId = compositeId)
	// admId is the composite ID ({sourceId}{1=tỉnh|2=phường})
	ClientListPlanningProjects(context.Context, *ClientListPlanningProjectsRequest) (*ListPlanningProjectsResponse, error)
	mustEmbedUnimplementedQHPlanningServiceServer()
}

